+					t.Errorf("failed to get recipient: %s", err)
+				}
+				if from == "" {
+					t.Fatal("expected sender, got empty string")
+				}
+				if !strings.EqualFold(from, addr.String()) {
+					t.Errorf("sender don't match, expected: %s, got: %s", addr.String(), from)
